def colorize_json(s):
    yellow = "\\x1b[33m"
    blue = "\\x1b[94m"
    green = "\\x1b[32m"
    reset = "\\x1b[0m"
    # Simple coloring: color braces/brackets yellow, keys blue, values green
    # We'll process per line
    lines = s.split("\\n")
    out_lines = []
    for line in lines:
        if not line.strip():
