    return "\\n".join(out_lines)

def colorize_xml(s):
    yellow = "\\x1b[33m"
    green = "\\x1b[32m"
    blue = "\\x1b[94m"
    reset = "\\x1b[0m"
    # comments blue
    s = re.sub(r'<!--.*?-->', lambda m: f"{blue}{m.group(0)}{reset}", s, flags=re.DOTALL)
    # CDATA blue
    s = re.sub(r'<!\\[CDATA\\[.*?\\]\\]>', lambda m: f"{blue}{m.group(0)}{reset}", s, flags=re.DOTALL)
    # doctype
    def repl_doctype(m):
        inner = m.group(0)
        mm = re.match(r'(<\\!)(doctype)(\\s*)(.*?)(\\s*>)$', inner, re.IGNORECASE|re.DOTALL)
        if mm:
            return f"{yellow}{mm.group(1)}{mm.group(2)}{reset}{mm.group(3)}{mm.group(4)}{yellow}{mm.group(5)}{reset}"
        else:
            return f"{yellow}<!{reset}{inner[2:-1]}{yellow}>{reset}"
    s = re.sub(r'<\\!doctype[^>]*>', repl_doctype, s, flags=re.IGNORECASE)
    # PI <? ... ?>
    def repl_pi(m):
        content = m.group(0)
        inner = content[2:-2]
        def repl_attr(mm):
            return f'{mm.group(1)}{green}{mm.group(2)}{reset}'
        inner_c = re.sub(r'(\\=\\s*)("[^"]*"|\\'[^\\']*\\')', repl_attr, inner)
        return f"{yellow}<?{reset}{inner_c}{yellow}?>{reset}"
    s = re.sub(r'<\\?.*?\\?>', repl_pi, s, flags=re.DOTALL)
    # tags
    def repl_tag(m):
        tc = m.group(0)
        if tc.startswith("</"):
            return f"{yellow}{tc}{reset}"
        inner = tc[1:-1]
        is_self = inner.endswith("/")
        if is_self:
            inner = inner[:-1].rstrip()
        parts = inner.split(None,1)
        tag_name = parts[0] if parts else ""
        rest = parts[1] if len(parts)>1 else ""
        def repl_attr2(mm):
            return f'{mm.group(1)}{green}{mm.group(2)}{reset}'
        rest_c = re.sub(r'(\\=\\s*)("[^"]*"|\\'[^\\']*\\')', repl_attr2, rest)
        if rest_c:
            rest_c = " " + rest_c if not rest_c.startswith(" ") else rest_c
        if is_self:
            return f"{yellow}<{tag_name}{reset}{rest_c}{yellow}/>{reset}"
        else:
            return f"{yellow}<{tag_name}{reset}{rest_c}{yellow}>{reset}"
    s = re.sub(r'<[^>]+>', repl_tag, s)
    return s

def xml_to_json(content, is_html, depth):
    # Use ET for conversion
    try:
        dom = minidom.parseString(content)
        root_elem = None
        for node in dom.childNodes:
            if node.nodeType == node.ELEMENT_NODE:
                root_elem = node
                break
        if not root_elem:
            raise Exception("no root")
        def convert_elem(elem, curr_depth):
            # attrs
            attrs = {}
            if elem.attributes:
                for i in range(elem.attributes.length):
                    attr = elem.attributes.item(i)
                    attrs[attr.name] = attr.value
            # child elems and texts
            child_elems = []
            texts = []
            for child in elem.childNodes:
                if child.nodeType == child.TEXT_NODE or child.nodeType == child.CDATA_SECTION_NODE:
                    if child.data.strip() != "":
                        texts.append(child.data.strip())
                elif child.nodeType == child.ELEMENT_NODE:
                    child_elems.append(child)
            direct_text = "\\n".join(texts) if texts else ""
            if depth != -1 and curr_depth >= depth:
                # flatten
                all_texts = []
                def collect(e):
                    for c in e.childNodes:
                        if c.nodeType == c.TEXT_NODE or c.nodeType == c.CDATA_SECTION_NODE:
                            if c.data.strip() != "":
                                all_texts.append(c.data.strip())
                        elif c.nodeType == c.ELEMENT_NODE:
                            collect(c)
                collect(elem)
                return "\\n".join(all_texts) if all_texts else ""
            obj = {}
            for k,v in attrs.items():
                obj["@"+k] = v
            groups = {}
            for child in child_elems:
                tag = child.tagName
                if is_html:
                    tag = tag.lower()
                conv = convert_elem(child, curr_depth+1)
                if tag not in groups:
                    groups[tag] = []
                groups[tag].append(conv)
            for tag, vals in groups.items():
                if len(vals)==1:
                    obj[tag]=vals[0]
                else:
                    obj[tag]=vals
            if not obj and not direct_text:
                return {}
            if not obj and direct_text:
                return direct_text
            if obj and direct_text:
                obj["#text"]=direct_text
                return obj
            return obj
        root_tag = root_elem.tagName
        if is_html:
            root_tag = root_tag.lower()
        converted = convert_elem(root_elem, 0)
        return {root_tag: converted}
    except Exception as e:
        # fallback ET
        try:
            root = ET.fromstring(content)
            def convert_et(elem, curr_depth):
                if depth != -1 and curr_depth >= depth:
                    all_texts = []
                    def collect(e):
                        if e.text and e.text.strip() != "":
                            all_texts.append(e.text.strip())
                        for ch in e:
                            collect(ch)
                            if ch.tail and ch.tail.strip() != "":
                                all_texts.append(ch.tail.strip())
                    collect(elem)
                    return "\\n".join(all_texts) if all_texts else ""
                attrs = elem.attrib
                texts = []
                if elem.text and elem.text.strip() != "":
                    texts.append(elem.text.strip())
                for ch in elem:
                    if ch.tail and ch.tail.strip() != "":
                        texts.append(ch.tail.strip())
                direct_text = "\\n".join(texts) if texts else ""
                obj = {}
                for k,v in attrs.items():
                    obj["@"+k]=v
                groups = {}
                for ch in elem:
                    tag = ch.tag
                    if "}" in tag:
                        tag = tag.split("}",1)[1]
                    if is_html:
                        tag = tag.lower()
                    conv = convert_et(ch, curr_depth+1)
                    if tag not in groups:
                        groups[tag]=[]
                    groups[tag].append(conv)
                for tag, vals in groups.items():
                    if len(vals)==1:
                        obj[tag]=vals[0]
                    else:
                        obj[tag]=vals
                if not obj and not direct_text:
                    return {}
                if not obj and direct_text:
                    return direct_text
                if obj and direct_text:
                    obj["#text"]=direct_text
                    return obj
                return obj
            root_tag = root.tag
            if "}" in root_tag:
                root_tag = root_tag.split("}",1)[1]
            if is_html:
                root_tag = root_tag.lower()
            conv = convert_et(root, 0)
            return {root_tag: conv}
        except Exception as e2:
            raise Exception(f"{e} {e2}")

def format_json_obj(obj, compact, depth, use_color):
    # depth already applied in xml_to_json, but for JSON input we need to apply depth here too
    # Apply depth to JSON object if needed (for JSON input)
    def apply_depth(o, curr):
        if depth != -1 and curr >= depth:
            def collect_leaves(x):
                if isinstance(x, dict):
                    leaves = []
                    for v in x.values():
                        leaves.extend(collect_leaves(v))
                    return leaves
                elif isinstance(x, list):
                    leaves = []
                    for item in x:
                        leaves.extend(collect_leaves(item))
                    return leaves
                elif isinstance(x, str):
                    return [x]
                else:
                    return [str(x)]
            leaves = collect_leaves(o)
            return "\\n".join(leaves)
        if isinstance(o, dict):
            return {k: apply_depth(v, curr+1) for k,v in o.items()}
        elif isinstance(o, list):
            return [apply_depth(item, curr+1) for item in o]
        else:
            return o

    if depth != -1:
        obj = apply_depth(obj, 0)

    if compact:
        out = json.dumps(obj, separators=(',', ': ')) + "\\n"
        # Actually json.dumps with separators (',', ': ') is default? For compact we want no newline but default separators keep space after colon
        # Use json.dumps(obj) which is compact
        out = json.dumps(obj) + "\\n"
        # But to match original compact which had spaces after colon? json.dumps without indent gives spaces? Let's use separators (',', ': ')
        # For simplicity, use json.dumps(obj, separators=(',', ': '))
        out = json.dumps(obj, separators=(',', ': ')) + "\\n"
        # Actually original compact for {"root":{"a":"hi"}} had space after colon? The earlier compact example {"root": {"a": "hi"}} had space after colon and comma. So separators (', ', ': ') is default.
        # json.dumps default already has that? Let's check: json.dumps({"a":1}) => '{"a": 1}' with space after colon, not after comma? Actually ', ' and ': '?
        # We'll use default json.dumps without indent which is compact and matches.
        out = json.dumps(obj) + "\\n"
        # But for nested, it would be compact single line
    else:
        out = json.dumps(obj, indent=2) + "\\n"

    if use_color:
        out = colorize_json(out)
    return out

def format_xml_content(content, indent_str, use_color):
    # Simplified XML formatter using minidom and custom pretty printer
    # Try to parse with minidom
    try:
        dom = minidom.parseString(content)
    except Exception as e:
        raise e

    # Collect output
    out_parts = []

    # Declaration
    decl_match = re.match(r'\\s*<\\?xml[^?]*\\?>', content)
    decl = ""
    if decl_match:
        decl = decl_match.group(0).strip()
    if dom.version:
        if decl:
            out_parts.append(decl + "\\n")
        else:
            enc = dom.encoding
            if enc:
                out_parts.append(f'<?xml version="{dom.version}" encoding="{enc}"?>\\n')
            else:
                out_parts.append(f'<?xml version="{dom.version}"?>\\n')
    else:
        if decl:
            out_parts.append(decl + "\\n")

    for node in dom.childNodes:
        if node.nodeType == node.DOCUMENT_TYPE_NODE:
            name = node.name
            # publicId, systemId handling
            # For simplicity, reconstruct as <!doctype name>
            # Try to get original text from content? We'll search for <!DOCTYPE ...> in content
            m = re.search(r'<!DOCTYPE[^>]*>', content, re.IGNORECASE)
            if m:
                # lower case doctype keyword
                orig = m.group(0)
                # replace DOCTYPE case-insensitive first 9 chars
                # Find first space after <!DOCTYPE
                # We'll do: "<!doctype" + rest of orig[9:]
                rest = orig[9:]  # after "<!DOCTYPE"
                # rest includes space and name etc
                # Ensure first char is space?
                out_parts.append(f"<!doctype{rest}>\\n")
            else:
                out_parts.append(f"<!doctype {name}>\\n")
        elif node.nodeType == node.COMMENT_NODE:
            out_parts.append(f"<!--{node.data}-->\\n")
        elif node.nodeType == node.ELEMENT_NODE:
            out_parts.append(format_minidom_element(node, 0, indent_str))

    result = "".join(out_parts)
    if use_color:
        result = colorize_xml(result)
    return result

def format_minidom_element(elem, level, indent_str):
    # Get attributes
    attrs = []
    if elem.attributes:
        for i in range(elem.attributes.length):
            attr = elem.attributes.item(i)
            # Escape?
            val = attr.value
            # Replace " with &quot;?
            val_esc = val.replace('"', '&quot;')
            attrs.append(f'{attr.name}="{val_esc}"')
    attr_str = ""
    if attrs:
        attr_str = " " + " ".join(attrs)

    # Gather child nodes: element, text (non-whitespace), comment
    sig_children = []
    for child in elem.childNodes:
        if child.nodeType == child.TEXT_NODE or child.nodeType == child.CDATA_SECTION_NODE:
            if child.data.strip() == "":
                continue
            sig_children.append(child)
        elif child.nodeType == child.ELEMENT_NODE or child.nodeType == child.COMMENT_NODE:
            sig_children.append(child)

    indent = indent_str * level

    if not sig_children:
        return f"{indent}<{elem.tagName}{attr_str}/>\\n"

    # Only one text child
    if len(sig_children)==1 and sig_children[0].nodeType in (sig_children[0].TEXT_NODE, sig_children[0].CDATA_SECTION_NODE):
        txt = sig_children[0].data
        # Apply text formatting: split by \\n, rstrip trailing spaces each line
        lines = txt.split("\\n")
        lines = [ln.rstrip(" \\t\\r") for ln in lines]
        formatted = "\\n".join(lines)
        return f"{indent}<{elem.tagName}{attr_str}>{formatted}</{elem.tagName}>\\n"

    # Has element/comment children
    # Opening
    out = f"{indent}<{elem.tagName}{attr_str}>"

    # Check if first child is text
    first = sig_children[0]
    if first.nodeType in (first.TEXT_NODE, first.CDATA_SECTION_NODE):
        # text first
        # process first text: rstrip trailing spaces if next is element/comment
        txt = first.data
        # If next is element/comment, rstrip trailing spaces of last line?
        # For simplicity, rstrip trailing spaces
        # We'll handle later in loop
        pass

    # We'll process children with loop similar to earlier but simplified

    # For simplicity, we will output each child on new line indented, except text that is first?

    # Let's implement more accurate mixed handling:

    # If first child is text, output it directly after opening, then if next is element, newline

    # We'll build

    out = f"{indent}<{elem.tagName}{attr_str}>"
    for idx, child in enumerate(sig_children):
        is_first = (idx==0)
        is_last = (idx==len(sig_children)-1)
        next_child = sig_children[idx+1] if not is_last else None
        next_is_elem = next_child and next_child.nodeType in (next_child.ELEMENT_NODE, next_child.COMMENT_NODE)

        if child.nodeType in (child.TEXT_NODE, child.CDATA_SECTION_NODE):
            txt = child.data
            # For text, if it contains newline, preserve but rstrip trailing spaces of each line?
            # For mixed, we want to rstrip trailing spaces of text if next is element or if it's last (before closing)
            # We'll split by \\n and rstrip last line if next_is_elem or is_last
            lines = txt.split("\\n")
            if len(lines)>1:
                # keep all but last as is, last rstrip if needed
                if next_is_elem or is_last:
                    lines[-1] = lines[-1].rstrip(" \\t\\r")
                txt = "\\n".join(lines)
            else:
                if next_is_elem or is_last:
                    txt = txt.rstrip(" \\t\\r")
            # If this is first child, output directly after opening (no newline)
            # If not first, text follows previous element: if previous was element, we are at newline? Actually after previous element we have newline and indent? For text after element, we want it on same line as previous element's closing (no newline). Our previous element formatting ends with \\n, so we would need to not have newline.

            # For our simplified handling, we will just append txt directly
            # If previous child was element and we had newline before, we need to handle

            # For first child text, it follows opening directly
            if is_first:
                out += txt
            else:
                # Check if previous child was element/comment: then text should be on same line as previous element's closing (which currently ends with \\n). That would place text on new line, not same line. To make it same line, we need to remove trailing \\n from out before appending text

                # If previous was element/comment, out currently ends with "\\n" from previous formatted child, so we should strip that trailing newline and indent before appending text

                # Let's check if out ends with "\\n"
                if out.endswith("\\n"):
                    # Remove last newline and possibly indent?
                    # Our element formatting for child includes newline at end, so out ends with "\\n"
                    # For text after element, we want text immediately after previous element's closing, not on new line
                    # So we should remove the trailing newline from previous element's formatting

                    # But our previous element formatting was added as formatted child string that ends with "\\n"
                    # To handle, we can if previous was element, we already added its formatted string with newline. We need to strip that newline now

                    out = out.rstrip("\\n")
                    # Also strip trailing indent? Our formatted child ends with "\\n" after closing, no extra indent after. So stripping newline leaves "...</a>" then we add text directly: "...</a>mid"

                out += txt

            if next_is_elem:
                out += "\\n"
        else:
            # element or comment
            # Need newline before this element if not already at newline?
            if not out.endswith("\\n"):
                out += "\\n"
            # Format child
            if child.nodeType == child.ELEMENT_NODE:
                child_formatted = format_minidom_element(child, level+1, indent_str)
                # If next is text, strip trailing newline from child_formatted
                if next_is_elem is False and next_child and next_child.nodeType in (next_child.TEXT_NODE, next_child.CDATA_SECTION_NODE):
                    # next is text, so we want child closing and text on same line, so strip newline
                    child_formatted = child_formatted.rstrip("\\n")
                out += child_formatted
            else:  # comment
                # Format comment
                comment_indent = indent_str * (level+1)
                out += f"{comment_indent}<!--{child.data}-->\\n"
                if next_child and next_child.nodeType in (next_child.TEXT_NODE, next_child.CDATA_SECTION_NODE):
                    out = out.rstrip("\\n")

    # Closing
    # If last child was element/comment, closing on new line with indent
    # If last child was text, closing immediately after text
    last = sig_children[-1]
    if last.nodeType in (last.ELEMENT_NODE, last.COMMENT_NODE):
        if not out.endswith("\\n"):
            out += "\\n"
        out += f"{indent}</{elem.tagName}>\\n"
    else:
        out += f"</{elem.tagName}>\\n"

    return out

def format_html_content(content, indent_str, use_color):
    # Simplified HTML formatter using html.parser Node
    VOID_ELEMENTS = {"area","base","br","col","embed","hr","img","input","link","meta","param","source","track","wbr"}

    class Node:
        def __init__(self, tag=None, attrs=None, parent=None, is_text=False, text="", is_comment=False, is_doctype=False, doctype_text=""):
            self.tag = tag
            self.attrs = attrs or {}
            self.children = []
            self.parent = parent
            self.is_text = is_text
            self.text = text
            self.is_comment = is_comment
            self.is_doctype = is_doctype
            self.doctype_text = doctype_text

    class MyHTMLParser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=False)
            self.root = Node(tag="document")
            self.current = self.root
            self.stack = [self.root]

        def handle_starttag(self, tag, attrs):
            tag = tag.lower()
            attr_dict = {}
            for k,v in attrs:
                attr_dict[k] = v if v is not None else ""
            node = Node(tag=tag, attrs=attr_dict, parent=self.current)
            self.current.children.append(node)
            if tag not in VOID_ELEMENTS:
                self.stack.append(node)
                self.current = node

        def handle_endtag(self, tag):
            tag = tag.lower()
            for i in range(len(self.stack)-1, -1, -1):
                if self.stack[i].tag == tag:
                    while len(self.stack) > i:
                        self.stack.pop()
                    self.current = self.stack[-1] if self.stack else self.root
                    break

        def handle_data(self, data):
            if data == "":
                return
            node = Node(is_text=True, text=data, parent=self.current)
            self.current.children.append(node)

        def handle_comment(self, data):
            node = Node(is_comment=True, text=data, parent=self.current)
            self.current.children.append(node)

        def handle_decl(self, decl):
            node = Node(is_doctype=True, doctype_text=decl, parent=self.current)
            self.current.children.append(node)

    parser = MyHTMLParser()
    try:
        parser.feed(content)
    except:
        pass

    def format_node(node, level):
        ind = indent_str * level
        if node.is_doctype:
            # decl like "DOCTYPE html"
            text = node.doctype_text
            # lower first token
            parts = text.split(None,1)
            if len(parts)>=1 and parts[0].lower()=="doctype":
                rest = parts[1] if len(parts)>1 else ""
                return f"{ind}<!doctype {rest}>\\n" if rest else f"{ind}<!doctype html>\\n"
            else:
                return f"{ind}<!{text}>\\n"
        if node.is_comment:
            return f"{ind}<!--{node.text}-->\\n"
        if node.is_text:
            if node.text.strip() == "":
                return ""
            # For text, keep as is but strip? For html text-only we want to preserve
            return node.text

        # element
        attr_str = ""
        if node.attrs:
            parts = []
            for k,v in node.attrs.items():
                if v == "":
                    parts.append(k)
                else:
                    v_esc = v.replace('"', '&quot;')
                    parts.append(f'{k}="{v_esc}"')
            attr_str = " " + " ".join(parts) if parts else ""

        if node.tag in VOID_ELEMENTS:
            return f"{ind}<{node.tag}{attr_str}/>\\n"

        # sig children
        sig_children = []
        for child in node.children:
            if child.is_text:
                if child.text.strip() == "":
                    continue
                sig_children.append(child)
            else:
                sig_children.append(child)

        if not sig_children:
            return f"{ind}<{node.tag}{attr_str}></{node.tag}>\\n"

        if len(sig_children)==1 and sig_children[0].is_text:
            txt = sig_children[0].text.strip()
            return f"{ind}<{node.tag}{attr_str}>{txt}</{node.tag}>\\n"

        out = f"{ind}<{node.tag}{attr_str}>\\n"
        for child in sig_children:
            out += format_node(child, level+1)
        out += f"{ind}</{node.tag}>\\n"
        return out

    out_parts = []
    for child in parser.root.children:
        out_parts.append(format_node(child, 0))

    result = "".join(out_parts)
    if use_color:
        result = colorize_xml(result)
    return result

def do_xpath_simple(content, expr, is_single, is_html, node_flag, indent_str, use_color):
    # Use ET for simple xpath
    # This is the same as do_xpath earlier but simplified

    # Attribute extraction handling
    attr_match = re.search(r'/@([^/@]+)$', expr)
    extract_attr = None
    elem_path = expr
    if attr_match:
        extract_attr = attr_match.group(1)
        elem_path = expr[:attr_match.start()]

    # Try to parse with minidom
    try:
        dom = minidom.parseString(content)
        root_elem = None
        for node in dom.childNodes:
            if node.nodeType == node.ELEMENT_NODE:
                root_elem = node
                break
        if not root_elem:
            return ("", "", 0, False)

        # Helper functions
        def find_all_by_tag(start, tag):
            res = []
            def traverse(n):
                for child in n.childNodes:
                    if child.nodeType == child.ELEMENT_NODE:
                        ct = child.tagName.lower() if is_html else child.tagName
                        if ct == tag or tag=="*":
                            res.append(child)
                        traverse(child)
            traverse(start)
            return res

        def find_children_by_tag(parent, tag):
            res = []
            for child in parent.childNodes:
                if child.nodeType == child.ELEMENT_NODE:
                    ct = child.tagName.lower() if is_html else child.tagName
                    if ct == tag or tag=="*":
                        res.append(child)
            return res

        def eval_path(path, contexts):
            if not path:
                return contexts
            if path.startswith("//"):
                rest = path[2:]
                parts = rest.split("/")
                first_tag = parts[0]
                remaining = "/".join(parts[1:])
                found = []
                for ctx in contexts:
                    if ctx.nodeType == ctx.DOCUMENT_NODE:
                        for child in ctx.childNodes:
                            if child.nodeType == child.ELEMENT_NODE:
                                ct = child.tagName.lower() if is_html else child.tagName
                                if ct == first_tag or first_tag=="*":
                                    found.append(child)
                                found.extend(find_all_by_tag(child, first_tag))
                    else:
                        ct = ctx.tagName.lower() if is_html else ctx.tagName
                        if ct == first_tag or first_tag=="*":
                            found.append(ctx)
                        found.extend(find_all_by_tag(ctx, first_tag))
                if not remaining:
                    return found
                return eval_path(remaining, found)
            elif path.startswith("/"):
                parts = [p for p in path.split("/") if p!=""]
                cur = contexts
                for idx, part in enumerate(parts):
                    nxt = []
                    for ctx in cur:
                        if ctx.nodeType == ctx.DOCUMENT_NODE:
                            for child in ctx.childNodes:
                                if child.nodeType == child.ELEMENT_NODE:
                                    ct = child.tagName.lower() if is_html else child.tagName
                                    if ct == part or part=="*":
                                        nxt.append(child)
                        else:
                            nxt.extend(find_children_by_tag(ctx, part))
                    cur = nxt
                return cur
            else:
                parts = [p for p in path.split("/") if p!=""]
                cur = contexts
                for part in parts:
                    nxt = []
                    for ctx in cur:
                        if ctx.nodeType == ctx.DOCUMENT_NODE:
                            for child in ctx.childNodes:
                                if child.nodeType == child.ELEMENT_NODE:
                                    ct = child.tagName.lower() if is_html else child.tagName
                                    if ct == part or part=="*":
                                        nxt.append(child)
                        else:
                            nxt.extend(find_children_by_tag(ctx, part))
                    cur = nxt
                return cur

        matched = eval_path(elem_path, [dom])

        if extract_attr:
            lines = []
            for elem in matched:
                if elem.nodeType == elem.ELEMENT_NODE:
                    val = elem.getAttribute(extract_attr)
                    if val != "":
                        lines.append(val)
            out = "\\n".join(lines)
            if out:
                out += "\\n"
            return (out, "", 0, False)
        else:
            if node_flag:
                out_parts = []
                for elem in matched:
                    out_parts.append(format_minidom_element(elem, 0, indent_str))
                out = "".join(out_parts)
                if is_single and matched:
                    out = format_minidom_element(matched[0], 0, indent_str)
                if use_color:
                    out = colorize_xml(out)
                return (out, "", 0, False)
            else:
                lines = []
                for elem in matched:
                    texts = []
                    def collect(n):
                        for child in n.childNodes:
                            if child.nodeType in (child.TEXT_NODE, child.CDATA_SECTION_NODE):
                                texts.append(child.data)
                            elif child.nodeType == child.ELEMENT_NODE:
                                collect(child)
                    collect(elem)
                    lines.append("".join(texts))
                out = "\\n".join(lines)
                if out:
                    out += "\\n"
                if is_single and lines:
                    out = lines[0] + "\\n" if lines else ""
                return (out, "", 0, False)

    except Exception as e:
        return ("", "", 0, False)

def do_css_query_simple(content, query_expr, attr_name, node_flag, is_html, indent_str, use_color):
    VOID_ELEMENTS = {"area","base","br","col","embed","hr","img","input","link","meta","param","source","track","wbr"}

    class Node:
        def __init__(self, tag=None, attrs=None, parent=None, is_text=False, text="", is_comment=False, is_doctype=False, doctype_text=""):
            self.tag = tag
            self.attrs = attrs or {}
            self.children = []
            self.parent = parent
            self.is_text = is_text
            self.text = text
            self.is_comment = is_comment
            self.is_doctype = is_doctype
            self.doctype_text = doctype_text

    class MyHTMLParser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=False)
            self.root = Node(tag="document")
            self.current = self.root
            self.stack = [self.root]

        def handle_starttag(self, tag, attrs):
            tag = tag.lower() if is_html else tag
            attr_dict = {}
            for k,v in attrs:
                attr_dict[k] = v if v is not None else ""
            node = Node(tag=tag, attrs=attr_dict, parent=self.current)
            self.current.children.append(node)
            if tag not in VOID_ELEMENTS:
                self.stack.append(node)
                self.current = node

        def handle_endtag(self, tag):
            tag = tag.lower() if is_html else tag
            for i in range(len(self.stack)-1, -1, -1):
                if self.stack[i].tag == tag:
                    while len(self.stack) > i:
                        self.stack.pop()
                    self.current = self.stack[-1] if self.stack else self.root
                    break

        def handle_data(self, data):
            node = Node(is_text=True, text=data, parent=self.current)
            self.current.children.append(node)

        def handle_comment(self, data):
            node = Node(is_comment=True, text=data, parent=self.current)
            self.current.children.append(node)

        def handle_decl(self, decl):
            node = Node(is_doctype=True, doctype_text=decl, parent=self.current)
            self.current.children.append(node)

    parser = MyHTMLParser()
    try:
        parser.feed(content)
    except:
        pass

    all_elements = []
    def collect(nodes):
        for n in nodes:
            if n.tag:
                all_elements.append(n)
                collect(n.children)
    collect(parser.root.children)

    # Parse selector
    simple_selectors = []
    combinators = []
    child_groups = [g.strip() for g in query_expr.split(">")]
    for gi, group in enumerate(child_groups):
        parts = [p for p in re.split(r'\\s+', group) if p != ""]
        for pi, part in enumerate(parts):
            simple_selectors.append(part)
            if gi==0 and pi==0:
                combinators.append(None)
            else:
                if pi>0:
                    combinators.append(" ")
                else:
                    combinators.append(">")

    if not simple_selectors:
        return ("", "", 0, False)

    def matches_simple(node, simple):
        m = re.match(r'^([a-zA-Z0-9\\*_-]*)(.*)$', simple)
        if not m:
            return False
        tag_part = m.group(1)
        rest = m.group(2)
        if tag_part != "" and tag_part != "*":
            nt = node.tag.lower() if is_html else node.tag
            st = tag_part.lower() if is_html else tag_part
            if nt != st:
                return False
        classes = re.findall(r'\\.([a-zA-Z0-9_-]+)', rest)
        ids = re.findall(r'\\#([a-zA-Z0-9_-]+)', rest)
        if ids:
            nid = node.attrs.get("id","")
            for sid in ids:
                if nid != sid:
                    return False
        if classes:
            nclass = node.attrs.get("class","")
            nclasses = nclass.split()
            for sc in classes:
                if sc not in nclasses:
                    return False
        return True

    first_sel = simple_selectors[0]
    current = [n for n in all_elements if matches_simple(n, first_sel)]

    for idx in range(1, len(simple_selectors)):
        sel = simple_selectors[idx]
        comb = combinators[idx]
        nxt = []
        for node in current:
            if comb == ">":
                for child in node.children:
                    if child.tag and matches_simple(child, sel):
                        nxt.append(child)
            else:  # descendant
                def collect_desc(n):
                    res = []
                    for ch in n.children:
                        if ch.tag:
                            if matches_simple(ch, sel):
                                res.append(ch)
                            res.extend(collect_desc(ch))
                    return res
                nxt.extend(collect_desc(node))
        current = nxt

    # Attr extraction
    if attr_name != "":
        lines = []
        for node in current:
            val = node.attrs.get(attr_name)
            if val is None and is_html:
                for k,v in node.attrs.items():
                    if k.lower() == attr_name.lower():
                        val = v
                        break
            if val is not None:
                lines.append(val)
        out = "\\n".join(lines)
        if out:
            out += "\\n"
        return (out, "", 0, False)
    else:
        if node_flag:
            # node serialization
            def format_node(node, level):
                ind = indent_str * level
                if node.is_text:
                    return ""
                if node.is_comment:
                    return f"{ind}<!--{node.text}-->\\n"
                if node.is_doctype:
                    return f"{ind}<!doctype {node.doctype_text}>\\n" if node.doctype_text else f"{ind}<!doctype html>\\n"
                attr_str = ""
                if node.attrs:
                    parts = []
                    for k,v in node.attrs.items():
                        if v == "":
                            parts.append(k)
                        else:
                            v_esc = v.replace('"', '&quot;')
                            parts.append(f'{k}="{v_esc}"')
                    attr_str = " " + " ".join(parts) if parts else ""
                if node.tag in VOID_ELEMENTS:
                    return f"{ind}<{node.tag}{attr_str}/>\\n"
                # sig children
                sig = []
                for ch in node.children:
                    if ch.is_text:
                        if ch.text.strip() == "":
                            continue
                        sig.append(ch)
                    else:
                        sig.append(ch)
                if not sig:
                    return f"{ind}<{node.tag}{attr_str}></{node.tag}>\\n"
                if len(sig)==1 and sig[0].is_text:
                    txt = sig[0].text.strip()
                    return f"{ind}<{node.tag}{attr_str}>{txt}</{node.tag}>\\n"
                out = f"{ind}<{node.tag}{attr_str}>\\n"
                for ch in sig:
                    out += format_node(ch, level+1)
                out += f"{ind}</{node.tag}>\\n"
                return out

            out_parts = []
            for node in current:
                out_parts.append(format_node(node, 0))
            out = "".join(out_parts)
            if use_color:
                out = colorize_xml(out)
            return (out, "", 0, False)
        else:
            lines = []
            for node in current:
                texts = []
                def collect_text(n):
                    for ch in n.children:
                        if ch.is_text:
                            if ch.text.strip() != "":
                                texts.append(ch.text.strip())
                        elif ch.tag:
                            collect_text(ch)
                collect_text(node)
                lines.append("".join(texts))
            out = "\\n".join(lines)
            if out:
                out += "\\n"
            return (out, "", 0, False)

def process_content(content, flags, is_file=False):
    use_color = False
    if flags["color"]:
        use_color = True
    elif flags["no-color"]:
        use_color = False
    else:
        use_color = sys.stdout.isatty()

    indent_size = flags["indent"]
    use_tab = flags["tab"]
    indent_str = "\\t" if use_tab else " " * indent_size

    is_html = flags["html"]
    is_json_output = flags["json"]
    xpath_expr = flags["xpath"]
    extract_expr = flags["extract"]
    query_expr = flags["query"]
    attr_name = flags["attr"]
    node_flag = flags["node"]
    compact = flags["compact"]
